/* @autogenerated */
import { Component, computed, effect, input, OnDestroy, OnInit, output, Signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { configValue } from '@shared/context/config/app-config.service';
import { Logger } from '@shared/context/observability/logger.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService, ContextValue } from '@shared/context/state/app-state.service';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatIconModule } from '@angular/material/icon';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { MatToolbarModule } from '@angular/material/toolbar';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { SelectorProvider } from '@shared/data/selector-provider';
import { EditableSelectoneComponent } from '@shared/toolkit/editable/editable-selectone/editable-selectone.component';
import { FormLayoutComponent } from '@shared/toolkit/form-layout/form-layout.component';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'app-toolbar',
  standalone: true,
  imports: [
    CommonModule,
    MatButtonModule,
    MatIconModule,
    MatToolbarModule,
    MatMenuModule,
    FormLayoutComponent,
    ReactiveFormsModule,
    EditableSelectoneComponent,
  ],
  templateUrl: './toolbar.component.html',
  styleUrl: './toolbar.component.scss',
})
export class ToolbarComponent implements OnInit, OnDestroy {
  menuClicked = output<void>();
  user = input<UserInfo | null>();
  providers = input<{ [key: string]: SelectorProvider<any, any> }>();

  providerList = computed(() => {
    const providers = this.providers();
    const values = [] as { key: string; value: SelectorProvider<any, any> }[];
    if (providers) {
      Object.entries(providers).forEach(([key, value]) => {
        values.push({
          key,
          value,
        });
      });
    }
    return values;
  });

  readonly form: FormGroup;
  title: Signal<string | undefined>;
  accountUrl: Signal<string | undefined>;

  currentLanguage: Signal<string | undefined>;
  currentTenant: Signal<string | undefined>;

  private init = false;
  private controlObservers = new Subscription();
  private subscriptions = new Subscription();

  public constructor(
    private readonly identity: IdentityService,
    private readonly appstate: AppStateService,
    private readonly logger: Logger,
  ) {
    this.form = new FormGroup({});
    this.title = configValue('meta.title');
    this.currentLanguage = toSignal(appstate.language);
    this.currentTenant = toSignal(appstate.tenant);
    this.accountUrl = configValue('identity.main.profile');

    effect(() => {
      this.syncProviders(this.providers());
    });
  }

  ngOnInit(): void {
    this.subscriptions.add(
      this.form.valueChanges.subscribe((value) => {
        Object.entries(value).forEach(([key, value]) => {
          if (value !== '') {
            this.appstate.context[key].set(ContextValue.fixed(key, value));
          }
        });
      }),
    );
    this.init = true;
    this.syncProviders(this.providers());
  }

  ngOnDestroy(): void {
    this.controlObservers.unsubscribe();
    this.subscriptions.unsubscribe();
  }

  toogleMenu(): void {
    this.menuClicked.emit();
  }

  login(): void {
    this.identity.login('main');
  }

  logout(): void {
    this.identity.logout('main');
  }

  account(): void {
    let target = this.accountUrl()!;
    let tenant = this.currentTenant();
    if (tenant) {
      target = target.replace('{{tenant}}', tenant);
    }
    document.location = target;
  }

  private syncProviders(providers?: { [key: string]: SelectorProvider<any, any> }) {
    if (this.init && providers) {
      this.controlObservers.unsubscribe();
      this.controlObservers = new Subscription();
      Object.keys(this.form.controls).forEach((key) => {
        this.form.removeControl(key);
      });
      Object.keys(providers).forEach((key) => {
        this.form.addControl(key, new FormControl<string>(''));
        this.controlObservers.add(
          this.appstate.context[key].subscribe((ctxVal) => {
            if (ctxVal) {
              this.form.controls[ctxVal?.label].setValue(ctxVal.value);
            }
          }),
        );
      });
    }
  }
}
